package app.rwun;

import android.app.*;import android.app.job.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.json.*;

/** Optional services and preferences kept separate from the GPS recorder and training domain. */
public final class FeaturesActivity extends Activity {
  private final UiKit.Palette palette=new UiKit.Palette(true);private LinearLayout body;private TextView status;private RunStore store;private boolean busy;private String screen;private final ExecutorService worker=Executors.newSingleThreadExecutor();
  public void onCreate(Bundle saved){super.onCreate(saved);store=new RunStore(this);screen=getIntent().getStringExtra("screen");if(screen==null||screen.equals("strength"))screen="help";show();}
  @Override public void finish(){if(busy&&status!=null){status.setText("Wait for the current operation to finish.");return;}super.finish();}
  protected void onDestroy(){worker.shutdown();super.onDestroy();}
  private void show(){
    LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(palette.background);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});
    LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(UiKit.iconButton(this,palette,R.drawable.ic_arrow_back,"Back",this::finish),new LinearLayout.LayoutParams(dp(48),dp(48)));bar.addView(UiKit.label(this,switch(screen){case "plan"->"Training preferences";case "strava"->"Strava";case "help"->"Training hub";default->"Account & cloud backup";},18,palette.ink,true));root.addView(bar);
    ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(12),dp(20),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);status=UiKit.label(this,"",14,palette.primary,false);body.addView(status);
    try{switch(screen){case "plan":planning();break;case "strava":strava();break;case "help":help();break;default:cloud();}}catch(Exception e){status.setText(UserErrors.message(e));}
  }
  private int dp(int value){return UiKit.dp(this,value);}private void text(String value){body.addView(UiKit.label(this,value,15,palette.muted,false));}private void heading(String value){body.addView(UiKit.label(this,value,21,palette.ink,true));}
  private void action(String label,Runnable run){body.addView(UiKit.action(this,palette,label,()->{try{run.run();}catch(Exception e){status.setText(UserErrors.message(e));}}));}
  private EditText field(String label,String value,int input){text(label);EditText edit=new EditText(this);edit.setTextColor(palette.ink);edit.setInputType(input);edit.setSingleLine(true);edit.setText(value);body.addView(edit);return edit;}
  private Spinner choose(String label,String[] choices,int selected){text(label);Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,choices));spinner.setSelection(selected);body.addView(spinner);return spinner;}
  private void task(Callable<String> work,Runnable after){if(busy){status.setText("An operation is already running.");return;}busy=true;status.setText("Working…");worker.submit(()->{String message;boolean success=false;try{message=work.call();success=true;}catch(Exception e){message=UserErrors.message(e);}final String result=message;final boolean ok=success;runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing())return;if(ok&&after!=null)after.run();status.setText(result);});});}
  private void planning(){
    var config=store.config();if(config==null){text("Create a plan first.");return;}JSONObject options=store.options();heading("Train around your week");text("Changes apply from the next full plan week. Past sessions and this week stay unchanged. Availability is not a reason to add catch-up runs.");
    Spinner mode=choose("Programme",PlanPreferences.MODES.toArray(new String[0]),Math.max(0,PlanPreferences.MODES.indexOf(options.optString("mode","Race preparation"))));
    Set<Integer> selected=new HashSet<>();JSONArray prior=options.optJSONArray("weekdays");if(prior!=null)for(int i=0;i<prior.length();i++)selected.add(prior.optInt(i));else for(var session:new PlanEngine().generate(config,store.profile()))if(session.date().isBefore(config.start().plusWeeks(1)))selected.add(session.date().getDayOfWeek().getValue());
    List<CheckBox> boxes=new ArrayList<>();for(DayOfWeek day:DayOfWeek.values()){CheckBox box=new CheckBox(this);box.setText(day.toString());box.setTextColor(palette.ink);box.setChecked(selected.contains(day.getValue()));body.addView(box);boxes.add(box);}text("Choose exactly "+config.days()+" days.");
    Spinner longDay=choose("Long easy run day",Arrays.stream(DayOfWeek.values()).map(Enum::toString).toArray(String[]::new),options.optInt("longDay",7)-1);
    action("Save training preferences",()->{try{if(!store.checkpoint().isEmpty())throw new IllegalStateException("Finish or recover the pending run first");Set<DayOfWeek> days=new HashSet<>();JSONArray array=new JSONArray();for(int i=0;i<boxes.size();i++)if(boxes.get(i).isChecked()){days.add(DayOfWeek.of(i+1));array.put(i+1);}PlanPreferences next=new PlanPreferences(PlanPreferences.MODES.get(mode.getSelectedItemPosition()),days,DayOfWeek.of(longDay.getSelectedItemPosition()+1));if(days.size()!=config.days())throw new IllegalArgumentException("Choose exactly "+config.days()+" days");options.put("mode",next.mode()).put("weekdays",array).put("longDay",next.longDay().getValue());store.options(options);status.setText("Training preferences saved. Review the upcoming weeks in Plan.");}catch(Exception e){status.setText(UserErrors.message(e));}});
    text("Race preparation progresses and tapers. Base building grows gently. Maintenance holds mileage with recovery weeks. Return to running reduces mileage and uses run/walk steps. These are original rules, not a validated equivalent to Runna coaching.");
  }
  private void cloud(){
    CloudClient client=new CloudClient(this);JSONObject settings;try{settings=client.vault.read();}catch(Exception e){text(UserErrors.message(e));action("Clear sync settings",()->{client.vault.clear();show();});return;}
    heading(settings.has("token")?"Account configured":"Optional private sync");text("Use your own deployed OpenRun HTTPS service. Backups are encrypted on this phone before upload. The server cannot recover your backup passphrase. No service is preconfigured.");
    if(!settings.has("token")){
      EditText url=field("HTTPS server URL",settings.optString("url"),android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);EditText email=field("Email",settings.optString("email"),android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText password=field("Account password · at least 12 characters","",129);EditText passphrase=field("Backup encryption passphrase · at least 12 characters","",129);
      for(String op:new String[]{"login","register"})action(op.equals("login")?"Sign in":"Create account",()->{String host=url.getText().toString().trim(),address=email.getText().toString().trim(),accountPassword=password.getText().toString(),backupPassword=passphrase.getText().toString();task(()->{String endpoint=CloudClient.endpoint(host);if(backupPassword.length()<12)throw new IllegalArgumentException("Use a backup passphrase of at least 12 characters");JSONObject config=new JSONObject().put("url",endpoint).put("email",address);JSONObject payload=new JSONObject().put("email",config.getString("email")).put("password",accountPassword);JSONObject result=CloudClient.request(config,"POST","/v1/"+op,payload.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),"application/json",-1).json();config.put("token",result.getString("token")).put("passphrase",backupPassword).put("revision",0);client.vault.write(config);return "Signed in. Your data has not been uploaded.";},this::show);});return;
    }
    text(settings.optString("email")+"\n"+settings.optString("url"));text("Last backup: "+settings.optString("lastSync","None"));if(settings.has("lastError"))text("Last background result: "+settings.optString("lastError"));
    action("Upload encrypted backup",()->task(()->{client.upload(this);return "Encrypted backup uploaded";},this::show));
    action("Restore cloud backup",()->new AlertDialog.Builder(this).setTitle("Replace local data?").setMessage("Restore replaces this phone’s plan, history and routes. Export a local backup first if it contains data you need to keep. Wrong passphrases and damaged backups are rejected before restore.").setNegativeButton("Cancel",null).setPositiveButton("Restore",(d,w)->task(()->{if(!store.checkpoint().isEmpty())throw new IllegalStateException("Finish or recover the pending run first");var reply=client.request("GET","/v1/backup",null,"",-1);var config=client.vault.read();byte[] zip=BackupCipher.decrypt(reply.data(),config.getString("passphrase").toCharArray());BackupManager.restoreFrom(this,store,new ByteArrayInputStream(zip));client.vault.update(current->{if(current.optString("token").equals(config.optString("token")))current.put("revision",reply.revision());});return "Cloud backup restored";},this::show)).show());
    Switch automatic=new Switch(this);automatic.setText("Automatic backup on unmetered networks");automatic.setTextColor(palette.ink);automatic.setChecked(settings.optBoolean("autoBackup",false));automatic.setOnCheckedChangeListener((b,on)->{try{client.vault.update(config->config.put("autoBackup",on));SyncJob.schedule(this,on);status.setText(on?"Periodic backup enabled. Android controls timing; it may delay jobs.":"Automatic backup disabled");}catch(Exception e){status.setText(UserErrors.message(e));}});body.addView(automatic);
    action("Sign out",()->task(()->{client.request("POST","/v1/logout",new byte[0],"application/json",-1);client.vault.clear();SyncJob.schedule(this,false);return "Signed out. Local training data is kept.";},this::show));
    action("Clear local sync credentials",()->{client.vault.clear();SyncJob.schedule(this,false);show();});
    action("Delete cloud account",()->new AlertDialog.Builder(this).setTitle("Delete cloud account and backup?").setMessage("This permanently deletes your account, encrypted cloud backup and server-side integration tokens. Local training data stays on this phone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->task(()->{client.request("DELETE","/v1/account",null,"",-1);client.vault.clear();SyncJob.schedule(this,false);return "Cloud account deleted";},this::show)).show());
  }
  private void strava(){
    CloudClient client=new CloudClient(this);if(!client.vault.read().has("token")){heading("Set up your account service first");text("Strava requires a registered application, OAuth credentials and an HTTPS callback on your OpenRun server. They are not bundled into the APK.");action("Account & cloud setup",()->{screen="cloud";show();});return;}
    heading("Strava activity connection");text("Authorization happens on Strava. Your server stores the provider tokens encrypted; the Android app never receives a Strava client secret.");
    action("Refresh connection status",()->task(()->{JSONObject result=client.request("GET","/v1/integrations",null,"",-1).json();return !result.optBoolean("strava_configured")?"Server needs Strava app credentials and an HTTPS callback.":result.optBoolean("strava_linked")?"Strava authorization is stored. Sync now checks whether it still works.":"Strava is not connected.";},null));
    action("Connect Strava",()->task(()->{String url=client.request("POST","/v1/strava/start",new byte[0],"application/json",-1).json().getString("url");Uri uri=Uri.parse(url);if(!"https".equals(uri.getScheme())||!"www.strava.com".equals(uri.getHost()))throw new IllegalStateException("Server returned an invalid authorization address");runOnUiThread(()->{if(!isDestroyed()&&!isFinishing())startActivity(new Intent(Intent.ACTION_VIEW,uri));});return "Complete authorization in your browser, then return here.";},null));
    action("Import recent Strava runs",()->task(()->{JSONArray rows=client.request("GET","/v1/strava/activities",null,"",-1).json().getJSONArray("activities");int added=0,skipped=0,review=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String id="strava:"+row.getLong("id");if(store.completed(id)){skipped++;continue;}double km=row.optDouble("distance")/1000;long seconds=row.optLong("elapsed_time");if(km<=0||km>250||seconds<1||seconds>180000){skipped++;continue;}String date=java.time.Instant.parse(row.getString("start_date")).atZone(ZoneId.systemDefault()).toLocalDate().toString();long started=java.time.Instant.parse(row.getString("start_date")).toEpochMilli();var result=store.importActivity(new RunStore.Run(id,date,km,(int)Math.max(1,seconds/60),5,2,false,"Strava","",0,seconds),false,RunStore.origin("Strava",String.valueOf(row.getLong("id")),started,started+seconds*1000));if(result==RunStore.ImportResult.ADDED)added++;else if(result==RunStore.ImportResult.REVIEW)review++;else skipped++;}return added+" runs imported · "+skipped+" skipped · "+review+" held for duplicate review in Progress. Duration is elapsed time; feedback was not inferred.";},null));
    action("Review possible duplicates",()->startActivity(new Intent(this,ImportReviewActivity.class)));
    action("Check latest upload",()->task(()->{long id=client.vault.read().optLong("lastUpload",0);if(id<=0)return "No upload has been queued on this phone.";JSONObject result=client.request("GET","/v1/strava/uploads/"+id,null,"",-1).json();return result.optString("status")+(result.isNull("error")?"":" · "+result.optString("error"));},null));
    action("Disconnect Strava",()->task(()->{client.request("DELETE","/v1/strava",null,"",-1);return "Strava access revoked and local server tokens removed";},null));
  }
  private void help(){
    store.event("guide_opened");
    heading("Your coaching library");
    text(CoachGuide.PROVENANCE);
    Spinner category=choose("Explore",new String[]{"All","Running","Planning","Recovery","Practical"},0);
    EditText search=field("Search coaching","",android.text.InputType.TYPE_CLASS_TEXT);
    LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);body.addView(results);
    Runnable refresh=()->{results.removeAllViews();var matches=CoachGuide.find(category.getSelectedItem().toString(),search.getText().toString());results.addView(UiKit.label(this,matches.size()+" guides · available offline",14,palette.muted,false));for(var article:matches)results.addView(UiKit.action(this,palette,article.title(),()->{AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle(article.title()).setMessage(article.body()+"\n\n"+(article.source().isEmpty()?"Original OpenRun practice suggestion.":"Background guidance: "+(article.source().equals(CoachGuide.CDC)?"CDC · activity intensity":"NHS · running guidance"))+"\n\nGenerated guidance; no qualified coach review.").setPositiveButton("Done",null);if(!article.source().isEmpty())dialog.setNeutralButton("Read source",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(article.source())));}catch(Exception e){status.setText("No browser is available to open this source.");}});dialog.show();}));};
    category.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){refresh.run();}});
    search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh.run();}public void afterTextChanged(android.text.Editable e){}});refresh.run();
  }
}
